CARDS.append({
 "topic_id": "adhd", "official_name": "Attention-Deficit/Hyperactivity Disorder", "plain_title": "A brain that runs on interest, not importance",
 "also_known_as": ["ADHD", "ADD (older term for the inattentive type)", "hyperkinetic disorder (ICD-10 term)"], "chapter_id": "neurodevelopmental", "card_type": "condition", "icd10cm_code": "F90.x (by presentation)",
 "language_convention": "mixed", "language_convention_note": "Uses 'person with ADHD' and 'ADHDer' interchangeably, reflecting community usage. Avoids 'suffers from'.",
 "one_liner": "A lifelong difference in attention, activity, and impulse control that makes some things much harder and some things easier.",
 "in_simple_words": "ADHD is a neurodevelopmental difference, present from childhood, in how the brain manages attention, energy, and impulses. Attention isn't 'missing'; it's hard to direct at will, so boring tasks feel impossible while interesting ones can absorb a person for hours. Many people also feel restless, act before thinking, lose things, and struggle with time and organization. It affects children and adults, girls as well as boys, and it responds very well to the right support and, for many, medication.",
 "what_it_can_feel_like": ["I have thirty browser tabs open in my head and the music is playing in one of them.", "I'm not lazy. I want to do the thing. There's a wall between me and starting.", "Medication was like putting on glasses. The world was the same, just suddenly in focus.", "I got diagnosed at 41. I grieved for the kid who was told she wasn't trying."],
 "common_signs": ["Trouble focusing on dull tasks, but able to hyperfocus on interesting ones", "Losing things, forgetting steps, and struggling with time and deadlines", "Restlessness, fidgeting, or a mind that never stops", "Acting or speaking before thinking", "Starting many things and finishing few", "Present since childhood and showing up in more than one setting"],
 "myths_vs_facts": [
  {"myth": "ADHD is just kids who can't sit still, and they grow out of it.", "fact": "Many people with ADHD are not hyperactive at all, and most carry it into adulthood, where it looks different but is still there."},
  {"myth": "Everyone's a bit ADHD these days.", "fact": "Everyone gets distracted. ADHD is a lifelong pattern that causes real difficulty in daily life, and it has clear brain-based differences."},
  {"myth": "ADHD medication turns kids into zombies or is a gateway to addiction.", "fact": "Taken as prescribed, ADHD medication is one of the most effective treatments in psychiatry, and treating ADHD lowers the risk of later substance problems."},
  {"myth": "Girls don't get ADHD.", "fact": "Girls and women are diagnosed less often because their ADHD is more often inattentive and masked. They are not less affected."}],
 "how_common": {"plain": "About 1 in 9 US children has been diagnosed with ADHD, and around 1 in 10 currently has it. Among adults the figure is thought to be about 1 in 20.",
  "figure": "11.4% of US children aged 3–17 ever diagnosed and 10.5% currently with ADHD (NSCH 2022, CDC); adult estimates about 4–6%", "source_ref": "src-cdc-adhd", "note": "Adult figure (CDC NCHS 2023 data brief ~6%) seen only in secondary sources; marked for verification."},
 "what_helps": {"plain_summary": "Support starts with understanding ADHD and changing the environment: structure, reminders, breaking tasks down, movement, and adjustments at school or work. For children over five, teens, and adults with ongoing difficulty, medication is highly effective and is prescribed and monitored by a specialist; stimulants like methylphenidate are usually first choice, with non-stimulant options available. Parent training helps young children, and CBT adapted for ADHD helps adults with organization and self-criticism.",
  "evidence_based_options": ["Psychoeducation and environmental changes at home, school, and work", "Stimulant medication (methylphenidate, lisdexamfetamine) and non-stimulant options, prescribed and monitored by a specialist", "Parent training programmes for younger children", "CBT adapted for ADHD, and ADHD coaching, for teens and adults"],
  "self_help_that_supports_care": ["External structure: timers, alarms, visual lists, one place for keys", "Body doubling: working alongside someone else", "Movement breaks and exercise, which genuinely help focus", "Connecting with other ADHDers, where the shame lifts fast"],
  "guideline_refs": ["src-nice-ng87"]},
 "when_to_reach_out": "If attention, restlessness, or impulsivity have caused real trouble since childhood at school, work, or home, ask a doctor about an ADHD assessment. Waits can be long; ask for support while you wait. If low mood or thoughts of self-harm come with it, which is common, seek help for those now.",
 "is_not": "Being distractible during a stressful month, or bored by one subject, is not ADHD. Anxiety, depression, sleep deprivation, and trauma can all look like ADHD and often co-occur, which is why assessment matters.",
 "hope_note": "People with ADHD run companies, create art, raise families, and solve problems nobody else sees. With the right support, the hard parts get smaller and the gifts get room.",
 "strengths_and_differences": "Many ADHDers bring creativity, energy, humour, quick thinking in a crisis, and the ability to dive deep into what fascinates them. These are real strengths, and they don't cancel the real difficulties with time, organization, and follow-through. Both are true.",
 "in_young_people": "In children, ADHD shows as trouble sitting still, waiting turns, following instructions, and finishing work; in girls it is often quieter: daydreaming, disorganization, and anxiety. Teachers often notice first. Treatment for children starts with parent and school support; medication is added when needed.",
 "across_cultures": "Diagnosis rates differ widely between countries, partly because expectations of children's behaviour differ. Children from minority and lower-income families are often diagnosed later. In some communities, ADHD is seen as poor discipline, which adds blame to an already hard situation.",
 "sub_sections": [{"title": "Presentations", "icd10cm_code": "F90.2 / F90.0 / F90.1", "text": "Combined (both inattention and hyperactivity-impulsivity), predominantly inattentive, or predominantly hyperactive-impulsive. The presentation can change over a lifetime."},
  {"title": "Other specified and unspecified ADHD", "icd10cm_code": "F90.8 / F90.9", "text": "Used when ADHD-type difficulties are clearly present and disabling but don't meet every criterion, for example when onset can't be confirmed before age 12."}],
 "related_topics": ["autism-spectrum-disorder", "specific-learning-disorder", "oppositional-defiant-disorder", "disruptive-mood-dysregulation-disorder", "major-depressive-disorder", "substance-use-disorders-overview", "tic-disorders"],
 "glossary_terms": ["executive-function", "executive-dysfunction", "hyperfocus", "time-blindness", "body-doubling", "rejection-sensitivity", "stimulant-medication", "late-diagnosis", "neurodivergent", "masking"],
 "safety": STD(["ADHD carries raised risk of self-harm and substance use; 'when to reach out' names this. Site-wide crisis link stays one tap away."]),
 "visual": VIS("Soft line illustration of a person at a desk with a visual timer, a colourful wall of sticky notes, headphones on, mid-flow on a project, a bicycle leaning by the door. Pastel green and orange.", "A person works at a desk with a visual timer and a wall of colourful sticky notes, headphones on, a bicycle by the door."),
 "communities": ["reddit-r-adhd", "chadd-online-communities", "nas-online-community"],
 "sources": [DSM("Neurodevelopmental Disorders"), src("src-cdc-adhd", "ADHD prevalence among US children and adolescents in 2022: diagnosis, severity, co-occurring disorders, and treatment", "CDC (Journal of Clinical Child & Adolescent Psychology; CDC Stacks)", "https://stacks.cdc.gov/view/cdc/160350", 2024, seen=True), NICE87,
  src("src-chadd", "About ADHD", "CHADD", "https://chadd.org/about-adhd/", seen=True)],
 "review": REV(["Verify adult prevalence source (CDC NCHS Data Brief, 2023 data).", "Confirm NG87 first-line wording for adults."])})

CARDS.append({
 "topic_id": "specific-learning-disorder", "official_name": "Specific Learning Disorder", "plain_title": "When reading, writing, or maths doesn't come the usual way",
 "also_known_as": ["dyslexia", "dyscalculia", "dysgraphia", "learning difficulties (UK)", "learning disabilities (US)"], "chapter_id": "neurodevelopmental", "card_type": "condition", "icd10cm_code": "F81.x (by area)",
 "language_convention": "mixed", "language_convention_note": "'Dyslexic person' and 'person with dyslexia' are both widely used and accepted; the card uses both.",
 "one_liner": "A lifelong difference in how the brain learns reading, writing, or maths, in a person who is otherwise capable.",
 "in_simple_words": "A specific learning disorder means one area of learning is much harder than expected for a person's age, intelligence, and schooling. Dyslexia affects reading and spelling; dysgraphia affects writing; dyscalculia affects numbers and maths. It has nothing to do with intelligence or effort: dyslexic people include surgeons, authors, and engineers. With the right teaching and tools, people learn and succeed, and understanding it early spares years of feeling 'stupid'.",
 "what_it_can_feel_like": ["The letters didn't move, like people think. They just never stuck, however hard I tried.", "I could explain the whole science project out loud. Writing it down took three times as long.", "Dyscalculia means I still count on my fingers at 35. I also run a successful business."],
 "common_signs": ["Slow, effortful, or inaccurate reading, or trouble understanding what's read", "Spelling that stays hard despite practice", "Writing that is slow, messy, or hard to organize", "Difficulty with number sense, maths facts, or calculation", "Skills well below what's expected for age, lasting six months or more", "Started during school years, often noticed early"],
 "myths_vs_facts": [
  {"myth": "Dyslexia means seeing letters backwards.", "fact": "It's mainly about how the brain processes the sounds in words. Letter reversals are common in all young children."},
  {"myth": "Kids with learning disorders aren't bright or aren't trying.", "fact": "By definition, a specific learning disorder occurs in someone whose overall ability is fine. The effort these students make is usually far greater than their peers'."},
  {"myth": "You grow out of it.", "fact": "It's lifelong, but with good teaching and tools, reading, writing, and maths improve and strategies carry people through."}],
 "how_common": {"plain": "Roughly 5 to 15 in every 100 school-age children have a specific learning disorder, with dyslexia the most common. Estimates vary with how it's defined.",
  "figure": "5–15% of school-age children across languages and cultures (DSM-5-TR text estimate); dyslexia estimates in the UK and US range from about 2% to 12% by study", "source_ref": "src-dsm", "note": "Figures from the DSM-5-TR text and a comparison of prevalence tables; needs a primary citation."},
 "what_helps": {"plain_summary": "The main 'treatment' is good teaching: structured, step-by-step, multisensory instruction in the skill that's hard, delivered by trained teachers or specialists, started as early as possible. Alongside that, accommodations such as extra time, audiobooks, text-to-speech, spell checkers, calculators, and oral exams let a person show what they know. Medication isn't a treatment for learning disorders, though ADHD often co-occurs and may be treated.",
  "evidence_based_options": ["Structured, multisensory literacy or numeracy instruction (for example phonics-based programmes for dyslexia)", "Formal school support plans with accommodations: extra time, assistive technology, alternative formats", "Assessment by an educational psychologist or specialist teacher", "Treating co-occurring ADHD or anxiety"],
  "self_help_that_supports_care": ["Audiobooks, text-to-speech, and speech-to-text tools", "Dyslexia-friendly fonts, coloured overlays if they help, and spacing", "Playing to strengths: explaining, building, drawing, speaking", "Connecting with others who learn the same way"],
  "guideline_refs": ["src-bda"]},
 "when_to_reach_out": "If a child is falling well behind in reading, writing, or maths despite effort and good teaching, ask the school and your doctor about an assessment. Adults who have always found these things unusually hard can be assessed too, and workplace support follows.",
 "is_not": "Falling behind because of missed schooling, learning in a second language, vision or hearing problems, or a general intellectual disability is not a specific learning disorder. Those need different support.",
 "hope_note": "People with learning disorders don't lack ability; they've been using the wrong tools. The right ones change everything.",
 "strengths_and_differences": "Dyslexic people often excel at big-picture thinking, spatial reasoning, storytelling, and problem-solving. Many people with dyscalculia are strong in language and the arts. Schools that measure only reading speed and arithmetic miss a great deal.",
 "in_young_people": "Signs can appear in preschool (trouble with rhymes, letter names, counting) and become clear once formal reading and maths start. Early assessment and support prevent the loss of confidence that often does more damage than the learning difference itself.",
 "across_cultures": "Dyslexia looks different in different writing systems and is harder to spot in languages with regular spelling. In many countries assessment is expensive or unavailable, and children are simply labelled slow.",
 "sub_sections": [{"title": "Areas", "icd10cm_code": "F81.0 / F81.81 / F81.2", "text": "With impairment in reading (dyslexia), in written expression (dysgraphia), or in mathematics (dyscalculia). A person can have more than one."}],
 "related_topics": ["adhd", "communication-disorders", "developmental-coordination-disorder", "intellectual-developmental-disorder", "school-and-work-problems"],
 "glossary_terms": ["learning-disability-vs-difficulty", "neurodivergent", "school-support-plans", "reasonable-accommodations", "working-memory"],
 "safety": STD(),
 "visual": VIS("Soft line illustration of a young person reading with headphones and a tablet, a parent nearby building a model with them, letters and numbers floating gently like leaves. Pastel green and lilac.", "A young person reads with headphones and a tablet while a parent builds a model beside them, letters and numbers drifting like leaves."),
 "communities": ["british-dyslexia-association-helpline", "nas-online-community"],
 "sources": [DSM("Neurodevelopmental Disorders"), src("src-bda", "British Dyslexia Association helpline and information", "British Dyslexia Association", "https://www.bdadyslexia.org.uk/services/helpline", seen=True),
  src("src-ida", "International Dyslexia Association", "International Dyslexia Association", "https://dyslexiaida.org/", note="Not opened.")],
 "review": REV(["Find a primary prevalence source.", "Add a dyscalculia-specific and a US dyslexia community after verification."])})

CARDS.append({
 "topic_id": "intellectual-developmental-disorder", "official_name": "Intellectual Developmental Disorder (Intellectual Disability)", "plain_title": "Learning and everyday skills that develop more slowly",
 "also_known_as": ["intellectual disability", "learning disability (UK usage)", "ID", "IDD", "mental retardation (outdated and offensive)"], "chapter_id": "neurodevelopmental", "card_type": "condition", "icd10cm_code": "F70–F73 (by severity)",
 "language_convention": "person-first", "language_convention_note": "'A person with an intellectual disability' or, in the UK, 'with a learning disability'. Self-advocates in the UK use 'learning disability'. Never 'retarded' or 'mentally handicapped'.",
 "one_liner": "A lifelong condition, from childhood, where reasoning, learning, and everyday skills develop more slowly and need more support.",
 "in_simple_words": "Intellectual developmental disorder means that from early childhood a person finds reasoning, learning, problem-solving, and everyday practical and social skills harder than most people. It ranges from mild, where someone lives independently with some support, to profound, where a person needs help with most things. The diagnosis rests on how a person manages daily life, not just a test score. People with intellectual disabilities have the same feelings, rights, and need for friendship as anyone, and with good support they live full lives.",
 "what_it_can_feel_like": ["I learn slower. I don't learn nothing. Give me time and I'll get it.", "My son needs help with money and forms. He also remembers every birthday in the family.", "The best thing anyone did for me was ask what I wanted, not decide for me."],
 "common_signs": ["Learning, reasoning, and problem-solving well below what's typical for age", "Needing support with everyday skills: communication, self-care, money, safety, relationships", "Delays noticed in early childhood: sitting, walking, talking, understanding", "Difficulties present across home, school, and community", "Lifelong, with support needs that can change over time"],
 "myths_vs_facts": [
  {"myth": "People with intellectual disabilities can't learn, work, or have relationships.", "fact": "Most can and do, with the right support. Many hold jobs, have partners, and live in their own homes."},
  {"myth": "It's the same as mental illness.", "fact": "It's a developmental difference, not an illness. People with intellectual disabilities can also have mental health conditions, and those are often missed."},
  {"myth": "IQ is what defines it.", "fact": "DSM-5-TR bases severity on adaptive functioning (daily skills), because that's what determines the support a person needs."}],
 "how_common": {"plain": "About 1 in 100 people worldwide have an intellectual disability, with higher rates in lower-income countries. Most cases are mild.",
  "figure": "Pooled prevalence 1.04% across 52 population studies (Maulik et al. 2011); Global Burden of Disease 2019 estimated 1.74% with wide regional variation", "source_ref": "src-maulik"},
 "what_helps": {"plain_summary": "There's no treatment for intellectual disability itself, and none is needed; what helps is support that fits the person: early intervention and therapies in childhood, inclusive education with a support plan, help with daily living skills, supported employment, and advocacy for rights. Mental health conditions, which are common and often missed, need their own treatment, adapted to the person. Any medication is prescribed and monitored by a doctor and should never be used just to manage behaviour.",
  "evidence_based_options": ["Early intervention services and speech, occupational, and physical therapy in childhood", "Inclusive education with an individual support plan", "Supported employment and supported living", "Adapted mental health care; avoiding medication used only to control behaviour"],
  "self_help_that_supports_care": ["Easy-read information and extra time to understand choices", "Self-advocacy groups where people with intellectual disabilities speak for themselves", "Family connecting with other families", "Planning for transitions: school leaving, adulthood, ageing parents"],
  "guideline_refs": ["src-nice-ng54"]},
 "when_to_reach_out": "If a young child is well behind others in understanding, talking, or learning skills, ask a doctor or health visitor for a developmental assessment. For adults, ask about a learning disability assessment, which opens the door to support and rights.",
 "is_not": "A specific learning disorder like dyslexia affects one skill in a person of typical ability. Delays caused by lack of schooling, hearing or vision problems, or a different first language are not intellectual disability. Dementia is a loss of skills later in life, not a developmental condition.",
 "hope_note": "With the right support and the chance to choose for themselves, people with intellectual disabilities live, work, love, and belong.",
 "strengths_and_differences": "People with intellectual disabilities are often described by families and friends as honest, warm, loyal, and good at living in the present. Every person has particular strengths; support should be built around them.",
 "in_young_people": "Delays are often noticed in the first years. 'Global developmental delay' is the label used under age five, before formal assessment is reliable. Early support makes a lasting difference.",
 "across_cultures": "Rates are higher where poverty, malnutrition, infections, and lack of antenatal care are common. In some communities disability brings deep shame and families hide children; in others, extended family provides strong natural support. Services work best when they respect the family's understanding.",
 "sub_sections": [{"title": "Severity levels", "icd10cm_code": "F70 (mild) / F71 (moderate) / F72 (severe) / F73 (profound)", "text": "Based on how much support a person needs in thinking, social, and practical skills, not on IQ alone."},
  {"title": "Global developmental delay and unspecified IDD", "icd10cm_code": "F88 / F79", "text": "Used for young children under five, or when assessment isn't possible yet, so support can start without waiting for a full diagnosis."}],
 "related_topics": ["autism-spectrum-disorder", "communication-disorders", "specific-learning-disorder", "neurobehavioral-disorder-prenatal-alcohol-exposure", "stereotypic-movement-disorder"],
 "glossary_terms": ["adaptive-functioning", "learning-disability-vs-difficulty", "neurodevelopmental", "guardianship", "reasonable-accommodations", "capacity"],
 "safety": STD(),
 "visual": VIS("Soft line illustration of a young adult serving coffee at a café counter with a colleague, both smiling, a small plant and a handwritten menu board. Pastel green and warm yellow.", "A young adult serves coffee at a café counter beside a smiling colleague, with a handwritten menu board."),
 "communities": ["nas-online-community"],
 "sources": [DSM("Neurodevelopmental Disorders"), src("src-maulik", "Prevalence of intellectual disability: a meta-analysis of population-based studies", "Research in Developmental Disabilities (Maulik et al.)", "https://pubmed.ncbi.nlm.nih.gov/21236634/", 2011, note="PubMed ID from memory; the figure (1.04%) was confirmed via search summaries."),
  src("src-nice-ng54", "Mental health problems in people with learning disabilities: prevention, assessment and management (NG54)", "NICE", "https://www.nice.org.uk/guidance/ng54", 2016, note="Not opened."),
  src("src-mencap", "Mencap", "Mencap (UK)", "https://www.mencap.org.uk/", note="Not opened.")],
 "review": REV(["Replace the placeholder community with verified self-advocacy and family groups (Mencap, The Arc, Inclusion International).", "Confirm Maulik PubMed link."])})

CARDS.append({
 "topic_id": "communication-disorders", "official_name": "Communication Disorders", "plain_title": "When speech, language, or conversation is hard",
 "also_known_as": ["language disorder", "developmental language disorder (DLD)", "speech sound disorder", "social (pragmatic) communication disorder"], "chapter_id": "neurodevelopmental", "card_type": "condition-group", "icd10cm_code": "F80.x",
 "language_convention": "person-first",
 "one_liner": "Lasting difficulties with speaking clearly, understanding or using language, or using language socially.",
 "in_simple_words": "Communication disorders are differences, starting in early childhood, in how a person produces speech sounds, understands and uses language, or uses language to connect with others. A child might speak late, be hard to understand, struggle to follow instructions or tell a story, or find conversation confusing. They aren't caused by not trying or by bad parenting, and they aren't a sign of low intelligence. Speech and language therapy helps a great deal, especially when it starts early.",
 "what_it_can_feel_like": ["I knew what I wanted to say. The words came out in the wrong order and people laughed.", "Nobody could understand him but me. The therapist gave us both the tools.", "Conversation is a dance everyone else learned without noticing. I had to be taught the steps."],
 "common_signs": ["Late or limited talking, small vocabulary, or short, muddled sentences", "Trouble understanding instructions, questions, or stories", "Speech that's hard for others to understand past the usual age", "Difficulty with the social side: taking turns, staying on topic, reading hints", "Difficulties present from early childhood, not caused by hearing loss or another condition"],
 "myths_vs_facts": [
  {"myth": "Late talkers always catch up on their own.", "fact": "Many do, but some have a language disorder that persists. Early assessment tells the difference, and early help works."},
  {"myth": "Speaking two languages causes language disorders.", "fact": "Bilingualism doesn't cause them. A child with a language disorder will have difficulty in both languages."},
  {"myth": "Social communication difficulties always mean autism.", "fact": "Social (pragmatic) communication disorder is diagnosed when there are no restricted interests or repetitive behaviours. Assessment tells them apart."}],
 "how_common": {"plain": "Language disorders are common: about 7 in 100 children starting school have a developmental language disorder, and speech sound difficulties are also common in young children.",
  "figure": "7.58% of children starting school had developmental language disorder of unknown origin (SCALES study, Surrey, England)", "source_ref": "src-scales"},
 "what_helps": {"plain_summary": "Speech and language therapy is the main support: targeted practice for speech sounds, building vocabulary and sentence skills, and teaching social communication directly. Parents and teachers are coached to build language into everyday life. Schools provide support plans. Hearing should always be checked. There is no medication for communication disorders.",
  "evidence_based_options": ["Speech and language therapy, individual or in groups", "Parent-coaching programmes for young children", "School-based language and communication support plans", "Hearing assessment and treatment of any hearing loss"],
  "self_help_that_supports_care": ["Talking, reading, and singing with children every day, following their interests", "Giving extra time to respond without jumping in", "Using pictures, gestures, and routines to support understanding", "Praising attempts, not just correct results"],
  "guideline_refs": ["src-rcslt"]},
 "when_to_reach_out": "If a child isn't using words by around 18 months, isn't combining words by two to three, is hard to understand by four, or struggles to follow conversation at school, ask a doctor or health visitor for a speech and language assessment. Adults can be assessed too.",
 "is_not": "Normal variation in when children talk, an accent, or learning a new language are not disorders. Difficulties caused by hearing loss, autism, or intellectual disability are described under those conditions, though speech and language therapy helps there too.",
 "hope_note": "Communication grows with support. Children who couldn't be understood at four are telling long stories at seven.",
 "strengths_and_differences": "Children with language disorders are often strong visual thinkers, builders, and problem-solvers. Their intelligence is intact; what they need is a different route to the same place.",
 "in_young_people": "Language disorders are often missed in school and mistaken for behaviour problems, shyness, or poor effort. Teenagers with undiagnosed language disorder are over-represented in exclusions and the justice system, which makes early identification important.",
 "across_cultures": "Children must be assessed in their strongest language, with interpreters where needed. Dialect differences are not disorders.",
 "sub_sections": [{"title": "Language disorder", "icd10cm_code": "F80.2", "text": "Lasting difficulty learning and using language: vocabulary, sentences, and conversation. Often called developmental language disorder (DLD) outside the DSM."},
  {"title": "Speech sound disorder", "icd10cm_code": "F80.0", "text": "Trouble producing speech sounds clearly enough to be understood, past the age when most children can."},
  {"title": "Social (pragmatic) communication disorder", "icd10cm_code": "F80.82", "text": "Difficulty using language socially: greetings, turn-taking, adjusting to the listener, understanding hints and jokes, without the repetitive behaviours seen in autism."},
  {"title": "Unspecified communication disorder", "icd10cm_code": "F80.9", "text": "Used when communication difficulties are clear but don't fit the patterns above."}],
 "related_topics": ["childhood-onset-fluency-disorder", "autism-spectrum-disorder", "specific-learning-disorder", "intellectual-developmental-disorder", "selective-mutism"],
 "glossary_terms": ["neurodevelopmental", "echolalia", "school-support-plans"],
 "safety": STD(),
 "visual": VIS("Soft line illustration of a child and a speech therapist playing with picture cards on a rug, the child pointing and laughing, speech bubbles with simple shapes. Pastel green and sky blue.", "A child and a speech therapist play with picture cards on a rug, the child pointing and laughing."),
 "communities": ["nas-online-community"],
 "sources": [DSM("Neurodevelopmental Disorders"), src("src-scales", "Surrey Communication and Language in Education Study (SCALES): prevalence of language disorder", "Royal College of Speech and Language Therapists / Norbury et al. 2016", "https://www.rcslt.org/wp-content/uploads/2022/07/Final-Report-Surrey-Communication-and-Language-in-Education-Study.pdf", 2016, seen=True),
  src("src-rcslt", "Royal College of Speech and Language Therapists", "RCSLT", "https://www.rcslt.org/", note="Not opened."),
  src("src-asha", "American Speech-Language-Hearing Association: public information", "ASHA", "https://www.asha.org/public/", note="Not opened.")],
 "review": REV(["Find verified parent communities (for example RADLD, Afasic UK) to replace the placeholder."])})

CARDS.append({
 "topic_id": "childhood-onset-fluency-disorder", "official_name": "Childhood-Onset Fluency Disorder (Stuttering)", "plain_title": "Stuttering",
 "also_known_as": ["stuttering", "stammering (UK)", "stutter"], "chapter_id": "neurodevelopmental", "card_type": "condition", "icd10cm_code": "F80.81",
 "language_convention": "mixed", "language_convention_note": "'Person who stutters' is preferred by most stuttering organizations; many adults also say 'I'm a stutterer'. Both appear here.",
 "one_liner": "Repeating, prolonging, or getting stuck on sounds and words, starting in childhood, beyond ordinary hesitation.",
 "in_simple_words": "Stuttering is a difference in the flow of speech: sounds or syllables repeat, stretch out, or get stuck so no sound comes out. It usually starts between ages two and five and has nothing to do with intelligence, nerves, or parenting. Most young children who stutter stop within a few years; for about one in a hundred people it continues into adulthood. Therapy helps at every age, and many people who stutter decide the goal is speaking freely, stutter and all.",
 "what_it_can_feel_like": ["It's not that I don't know the word. The word knows it's coming and the door slams.", "I spent twenty years swapping words to avoid the hard ones. Therapy let me say my own name.", "My son's stutter got worse when we told him to slow down. Then we learned to just listen."],
 "common_signs": ["Repeating sounds or syllables (li-li-like this)", "Stretching sounds out, or silent blocks where no sound comes", "Visible tension, blinking, or movements while trying to speak", "Avoiding certain words, situations, or speaking at all", "Starting in early childhood and continuing beyond six months"],
 "myths_vs_facts": [
  {"myth": "Stuttering is caused by anxiety or shyness.", "fact": "Stuttering is neurological and often runs in families. Anxiety can make it worse, but it doesn't cause it."},
  {"myth": "Telling someone to slow down or take a breath helps.", "fact": "It usually adds pressure. Giving time, keeping eye contact, and not finishing sentences is what helps."},
  {"myth": "People who stutter are less intelligent or confident.", "fact": "Stuttering has no link to intelligence. Many people who stutter are confident public speakers, actors, and leaders."}],
 "how_common": {"plain": "About 5 to 8 in every 100 children stutter at some point, usually starting between two and five. Around 1 in 100 adults stutters, with men affected about four times as often as women.",
  "figure": "Onset in at least 5% of children; persists in about 1% of the general population after puberty; male-to-female ratio about 4:1", "source_ref": "src-stutter-prev"},
 "what_helps": {"plain_summary": "For young children, therapy that coaches parents in responding to stuttering (for example the Lidcombe or Palin approaches) has good evidence and often leads to recovery. For older children and adults, speech therapy teaches techniques for easier speech and, just as important, reduces fear and avoidance so the person can say what they want to say. Peer support from other people who stutter is powerful. There is no medication for stuttering.",
  "evidence_based_options": ["Parent-led early intervention programmes for preschool children", "Speech and language therapy for older children and adults, combining fluency techniques with confidence and acceptance work", "CBT for the anxiety and avoidance that can build up around stuttering", "Self-help and peer support groups run by stuttering organizations"],
  "self_help_that_supports_care": ["Saying what you want to say, not swapping words", "Telling people you stutter, which takes the pressure off", "Connecting with other people who stutter", "For listeners: wait, keep natural eye contact, don't finish sentences"],
  "guideline_refs": ["src-stamma"]},
 "when_to_reach_out": "If a child's stuttering has lasted more than six months, started after age three and a half, runs in the family, or is causing distress or avoidance, ask for a speech and language therapy assessment; don't wait and see for too long. Adults can seek therapy at any age.",
 "is_not": "Everyone hesitates, repeats whole words, or says 'um' sometimes, especially when tired or excited; that's normal non-fluency. Stuttering that begins in adulthood after a brain injury, stroke, or severe stress is a different condition and needs medical assessment.",
 "hope_note": "Whether speech becomes smoother or not, people who stutter learn to say everything they want to say, and the world is slowly learning to listen.",
 "strengths_and_differences": "Many people who stutter describe becoming careful listeners, thoughtful speakers, and resilient advocates. The stuttering community has a strong, proud culture of its own.",
 "in_young_people": "Stuttering usually begins between two and five, often when language is developing fast. Early therapy works best, and it's gentle and play-based. Schools should know, so the child isn't marked down for not reading aloud.",
 "sub_sections": [{"title": "Adult-onset fluency disorder", "icd10cm_code": "F98.5", "text": "Stuttering that starts in adulthood, usually after a neurological event or severe psychological stress. Needs medical assessment to find the cause."}],
 "related_topics": ["communication-disorders", "social-anxiety-disorder", "tic-disorders", "selective-mutism"],
 "glossary_terms": ["avoidance", "cbt", "person-first-identity-first", "neurodivergent"],
 "safety": STD(),
 "visual": VIS("Soft line illustration of a young person speaking into a microphone at a small open-mic night, friends in the audience leaning in and listening, warm string lights. Pastel green and amber.", "A young person speaks into a microphone at a small open-mic night while friends lean in and listen under warm string lights."),
 "communities": ["stamma-uk"],
 "sources": [DSM("Neurodevelopmental Disorders"), src("src-stutter-prev", "Multiple community-based epidemiological study of childhood-onset fluency disorder (German claims data)", "Folia Phoniatrica et Logopaedica (Karger)", "https://karger.com/fpl/article/77/1/44/906844/Multiple-Community-Based-Epidemiological-Study-of", 2025, seen=True),
  src("src-stamma", "STAMMA: Help for people who stammer", "STAMMA (British Stammering Association)", "https://stamma.org/get-help/people-who-stammer", seen=True),
  src("src-nsa", "National Stuttering Association", "National Stuttering Association (US)", "https://westutter.org/", note="Not opened."),
  src("src-sf", "The Stuttering Foundation", "Stuttering Foundation of America", "https://www.stutteringhelp.org/", note="Not opened.")],
 "review": REV(["Verify US (NSA) and Australian stuttering communities and add them.", "Confirm the Karger citation details."])})

CARDS.append({
 "topic_id": "tic-disorders", "official_name": "Tic Disorders (including Tourette's Disorder)", "plain_title": "Tics and Tourette's",
 "also_known_as": ["Tourette syndrome", "TS", "tics", "persistent tic disorder", "provisional tic disorder"], "chapter_id": "neurodevelopmental", "card_type": "condition-group", "icd10cm_code": "F95.x",
 "language_convention": "mixed", "language_convention_note": "'Person with Tourette's' and 'Touretter' are both used in the community; the card uses person-first by default.",
 "one_liner": "Sudden, repeated movements or sounds that are hard to control, starting in childhood. Tourette's means both kinds for over a year.",
 "in_simple_words": "Tics are quick, repeated movements (blinking, head jerks, shrugging) or sounds (sniffing, throat clearing, words) that a person feels an urge to do and can only hold back for a while. They start in childhood, come and go, and worsen with stress, tiredness, or excitement. Tourette's means both motor and vocal tics for over a year. Tics are not deliberate, not a sign of anything 'wrong', and often ease by adulthood. Only a minority of people with Tourette's say rude words.",
 "what_it_can_feel_like": ["It's like a sneeze. You can hold it, but it builds until you have to let it out.", "People filmed my son in a shop. He was seven. Tourette's isn't a joke to the kids living it.", "My tics are part of me. I'd rather people understood them than that I spent my life hiding them."],
 "common_signs": ["Sudden, fast, repeated movements: blinking, grimacing, jerking, shrugging", "Sudden sounds: sniffing, throat clearing, grunting, or words", "An urge or itch-like feeling that builds before the tic", "Tics that come and go, change over time, and worsen with stress", "Starting before age 18, usually around five to seven", "In Tourette's, both movement and sound tics for over a year"],
 "myths_vs_facts": [
  {"myth": "Tourette's means shouting swear words.", "fact": "Swearing tics (coprolalia) affect only around one in ten people with Tourette's. Most tics are small movements and sounds."},
  {"myth": "People can stop tics if they really try.", "fact": "Tics can be held back briefly, at a cost; the urge builds and the tics come out later. Suppressing all day is exhausting."},
  {"myth": "Tics are caused by bad parenting or attention-seeking.", "fact": "Tic disorders are neurological and run in families. They have nothing to do with parenting or wanting attention."}],
 "how_common": {"plain": "About 1 in every 160 children has Tourette's, counting those not yet diagnosed, and around 1 in 330 has a diagnosis. Simpler, temporary tics are much more common, affecting perhaps 1 in 5 children at some point.",
  "figure": "Tourette's: 1 in 162 children (0.6%) including undiagnosed; 1 in 333 (0.3%) diagnosed, CDC. Persistent tic disorders may affect about 1.4 million people in the US", "source_ref": "src-cdc-tourette"},
 "what_helps": {"plain_summary": "Many tics need no treatment beyond understanding and school awareness. When tics hurt, embarrass, or interfere, a behavioural therapy called CBIT (comprehensive behavioural intervention for tics, built on habit reversal training) is the first choice. Medication can reduce tics when they are severe, prescribed and monitored by a specialist. Treating the ADHD, OCD, or anxiety that often come with tics usually helps most of all.",
  "evidence_based_options": ["Psychoeducation for the child, family, and school", "CBIT / habit reversal training", "Medication for severe tics, prescribed and monitored by a specialist", "Treatment of co-occurring ADHD, OCD, or anxiety"],
  "self_help_that_supports_care": ["Not drawing attention to tics; they fade when ignored and grow under scrutiny", "Good sleep and lower stress, which reduce tics", "A note for school: tic breaks, no penalties for noises, seating choices", "Peer support with other families and adults with tics"],
  "guideline_refs": ["src-cdc-tourette"]},
 "when_to_reach_out": "If a child's tics have lasted more than a few months, cause pain or embarrassment, or come with attention, mood, or obsessive problems, ask a doctor for a referral. Sudden, dramatic onset of tic-like movements in teens should also be assessed, as it can have other causes.",
 "is_not": "Fidgeting, habits like nail-biting, and the brief tics many young children have for a few weeks are not tic disorders. Repetitive movements that are rhythmic and soothing, like rocking, are stereotypies, a different thing. Compulsions in OCD are done on purpose to relieve anxiety, while tics are involuntary.",
 "hope_note": "Tics usually peak around age 10 to 12 and ease for most people by adulthood. Whether they fade or stay, people with Tourette's thrive in every walk of life.",
 "strengths_and_differences": "Many people with Tourette's describe quick reflexes, humour, creativity, and a deep sense of empathy for anyone who is different. The community is strong and often funny about itself, on its own terms.",
 "in_young_people": "Tics usually start around age five to seven and peak in the early teens. Schools can make a huge difference with simple adjustments. Bullying is common and should be addressed directly.",
 "across_cultures": "Tourette's exists worldwide with similar rates. In some communities tics are interpreted as spiritual or as bad behaviour, which can delay diagnosis. Awareness is improving thanks to advocacy by people with Tourette's.",
 "sub_sections": [{"title": "Tourette's disorder", "icd10cm_code": "F95.2", "text": "Multiple motor tics and at least one vocal tic for more than a year, starting before 18."},
  {"title": "Persistent (chronic) motor or vocal tic disorder", "icd10cm_code": "F95.1", "text": "Either motor or vocal tics, not both, for more than a year."},
  {"title": "Provisional tic disorder", "icd10cm_code": "F95.0", "text": "Tics present for less than a year. Many children's tics resolve in this window."},
  {"title": "Other specified and unspecified tic disorder", "icd10cm_code": "F95.8 / F95.9", "text": "For tic patterns that don't fit the above, for example tics starting after 18."}],
 "related_topics": ["adhd", "obsessive-compulsive-disorder", "stereotypic-movement-disorder", "autism-spectrum-disorder", "generalized-anxiety-disorder"],
 "glossary_terms": ["tic", "habit-reversal-training", "compulsion", "stimming", "neurodivergent"],
 "safety": STD(),
 "visual": VIS("Soft line illustration of a group of friends laughing around a picnic blanket in a park, one wearing a 'Tourette's awareness' badge, a frisbee mid-air. Pastel green and sky blue.", "Friends laugh around a picnic blanket in a park, one wearing an awareness badge, a frisbee in the air."),
 "communities": ["tourettes-action-uk", "tourette-scotland"],
 "sources": [DSM("Neurodevelopmental Disorders"), src("src-cdc-tourette", "Data and Statistics on Tourette Syndrome", "CDC", "https://www.cdc.gov/tourette-syndrome/data/", seen=True),
  src("src-taa", "Tourette Association of America", "Tourette Association of America", "https://tourette.org/", note="Not opened."),
  src("src-tourettes-action", "Tourettes Action", "Tourettes Action (UK)", "https://www.tourettes-action.org.uk/", note="Service listings seen on NHS and council directories; site itself not opened.")],
 "review": REV(["Verify Tourette Association of America support groups and r/Tourettes.", "Confirm CBIT guideline reference (AAN practice guideline 2019)."])})

CARDS.append({
 "topic_id": "developmental-coordination-disorder", "official_name": "Developmental Coordination Disorder", "plain_title": "When movement and coordination don't come easily",
 "also_known_as": ["DCD", "dyspraxia (common UK term)"], "chapter_id": "neurodevelopmental", "card_type": "condition", "icd10cm_code": "F82", "language_convention": "mixed",
 "language_convention_note": "'Person with DCD' or 'dyspraxic person'; the UK community mostly uses 'dyspraxic'.",
 "one_liner": "A lifelong difference in motor coordination that makes everyday physical tasks clumsier and slower than expected.",
 "in_simple_words": "Developmental coordination disorder means the brain finds it harder to plan and control movement. Children are slower to learn to dress, use cutlery, write, ride a bike, or catch a ball, and they bump into things more. It isn't laziness or carelessness, and it isn't caused by a muscle or nerve disease. It continues into adulthood, where it can affect driving, cooking, and organization. Occupational therapy and practical strategies help a lot, and many people find their own clever workarounds.",
 "what_it_can_feel_like": ["PE was humiliation twice a week. Nobody told me it had a name until I was 30.", "I can give a lecture to 200 people. I cannot tie a bow or pour without spilling.", "Once the OT showed him how to break tasks into steps, he stopped saying 'I'm rubbish at everything'."],
 "common_signs": ["Clumsiness: dropping, spilling, bumping into things, tripping", "Slow or messy handwriting, trouble with buttons, laces, cutlery", "Difficulty with ball games, riding a bike, or learning new physical skills", "Trouble planning and organizing tasks and movements", "Present since early childhood and affecting daily life or school"],
 "myths_vs_facts": [
  {"myth": "Clumsy kids just need more practice.", "fact": "Practice alone doesn't fix it, and repeated failure damages confidence. Targeted, task-based therapy works far better."},
  {"myth": "Children grow out of it.", "fact": "DCD is lifelong for most. Adults learn strategies and build on strengths, but the coordination difference remains."},
  {"myth": "DCD only affects movement.", "fact": "It often comes with difficulties in organization, time, and sometimes speech, and it frequently overlaps with ADHD and dyslexia."}],
 "how_common": {"plain": "About 5 to 6 in every 100 school-age children have DCD, boys more often than girls. It's one of the most common and least recognized neurodevelopmental conditions.",
  "figure": "5–6% of children aged 5–11 (DSM-5-TR text estimate; study estimates range from under 2% to around 10%)", "source_ref": "src-dsm", "note": "Needs a primary prevalence source."},
 "what_helps": {"plain_summary": "Occupational therapy and physiotherapy using task-based approaches, which teach the specific skills a person wants to learn by breaking them into steps and practising them, have the best evidence. Accommodations at school and work, like extra time, typing instead of handwriting, and clear step-by-step instructions, make a big difference. Confidence and mental health matter, as years of 'being clumsy' can hurt self-esteem.",
  "evidence_based_options": ["Task-oriented occupational therapy and physiotherapy (for example CO-OP)", "School and workplace accommodations: typing, extra time, modified PE", "Teaching specific daily skills step by step", "Support for self-esteem and any co-occurring ADHD or anxiety"],
  "self_help_that_supports_care": ["Choosing physical activities you enjoy, like swimming or martial arts, over competitive team sports", "Laying out clothes and tasks in order the night before", "Velcro, elastic laces, and other low-tech fixes without shame", "Joining the dyspraxia community online, where the tips are endless"],
  "guideline_refs": ["src-eacd"]},
 "when_to_reach_out": "If a child is far behind others in physical skills, avoids drawing, writing, or sport, or is often told off for clumsiness, ask a doctor or school about an occupational therapy assessment. Adults who have always struggled this way can also be assessed.",
 "is_not": "Normal variation in sportiness isn't DCD. Coordination problems caused by cerebral palsy, muscular dystrophy, vision problems, or a brain injury are different conditions with different care.",
 "hope_note": "With the right tools and a bit of ingenuity, people with DCD do everything they set their minds to, usually in their own creative way.",
 "strengths_and_differences": "Many dyspraxic people are determined, empathetic, strategic thinkers with strong verbal skills, precisely because they've had to find other routes to things most people never think about.",
 "in_young_people": "Signs are usually visible by preschool. School is where DCD causes most trouble, through handwriting, PE, and practical lessons. Formal support plans help, and so does an explanation the child can use: 'my brain plans movement differently'.",
 "related_topics": ["adhd", "specific-learning-disorder", "communication-disorders", "autism-spectrum-disorder"],
 "glossary_terms": ["executive-function", "occupational-therapist", "neurodivergent", "school-support-plans"],
 "safety": STD(),
 "visual": VIS("Soft line illustration of a child swimming happily in a pool lane while an adult cheers from the side, goggles pushed up, splash of water. Pastel green and aqua.", "A child swims happily down a pool lane with goggles pushed up while an adult cheers from the side."),
 "communities": ["nas-online-community"],
 "sources": [DSM("Neurodevelopmental Disorders"), src("src-eacd", "International clinical practice recommendations on the definition, diagnosis, assessment, intervention, and psychosocial aspects of developmental coordination disorder", "Developmental Medicine & Child Neurology (Blank et al., EACD)", "https://pubmed.ncbi.nlm.nih.gov/30644111/", 2019, note="PubMed ID from memory; must be confirmed.")],
 "review": REV(["The Dyspraxia Foundation (UK) closed in 2024; find current UK and US peer communities (e.g. Dyspraxia UK, DCD Ireland) and verify.", "Confirm EACD guideline link."])})

CARDS.append({
 "topic_id": "stereotypic-movement-disorder", "official_name": "Stereotypic Movement Disorder", "plain_title": "Repeated movements that are hard to stop and can cause harm",
 "also_known_as": ["stereotypies", "motor stereotypies", "self-injurious stereotypies"], "chapter_id": "neurodevelopmental", "card_type": "condition", "icd10cm_code": "F98.4", "language_convention": "person-first",
 "one_liner": "Repetitive, rhythmic, seemingly purposeless movements, like rocking or hand-flapping, that interfere with life or cause injury.",
 "in_simple_words": "Many children rock, flap, or twirl, especially when excited, and most of the time that's harmless and normal. Stereotypic movement disorder is diagnosed when repetitive movements take up so much time that they get in the way of play, learning, or daily life, or when they cause injury, like head-banging. It's more common in children with intellectual disability or autism. Care focuses on safety, understanding what the movement does for the child, and gentle ways to reduce harm.",
 "what_it_can_feel_like": ["Hand-flapping is how my body says happy. The only problem was other people's faces.", "His head-banging terrified us. The team helped us see what he was trying to tell us.", "I rock when I think. I'm 40 and I've stopped apologizing for it."],
 "common_signs": ["Repetitive, rhythmic movements: rocking, hand-flapping, waving, head-banging, hitting or biting oneself", "Movements that start in early childhood and seem to have no purpose", "Movements that take up a lot of time or interrupt activities", "In some children, movements that cause bruising, wounds, or other injury"],
 "myths_vs_facts": [
  {"myth": "All repetitive movements need to be stopped.", "fact": "Harmless stereotypies, including most autistic stimming, help with regulation and don't need treatment. Only movements that interfere or injure are a disorder."},
  {"myth": "Self-injury is attention-seeking.", "fact": "Self-injurious movements usually serve a function, such as relieving pain, distress, or overload, or communicating a need. Finding the function is the key to helping."},
  {"myth": "Medication is the main answer.", "fact": "Behavioural and environmental approaches come first. Medication is sometimes used for severe self-injury, prescribed and monitored by a specialist."}],
 "how_common": {"plain": "Simple stereotypies are common in young children. The disorder itself is uncommon in typically developing children and much more common in children with intellectual disability, especially severe disability.",
  "figure": "DSM-5-TR text: simple stereotypies common (3–4% of young children); self-injurious stereotypies in about 4–16% of people with intellectual disability, higher with greater severity", "source_ref": "src-dsm", "note": "Figures from the DSM-5-TR text; needs a primary source."},
 "what_helps": {"plain_summary": "The first step is a careful assessment of when the movement happens and what it achieves for the child, often by a behaviour specialist. Treatment then uses environmental changes, teaching other ways to meet the same need, and safety measures like protective equipment where needed. Any pain or medical cause is treated. For severe self-injury, medication may be considered, prescribed and monitored by a specialist. For harmless stereotypies, the best treatment is acceptance.",
  "evidence_based_options": ["Functional behavioural assessment and behaviour support plans", "Teaching replacement skills and communication", "Treating pain, discomfort, or medical causes", "Medication in some cases of severe self-injury, prescribed and monitored by a specialist"],
  "self_help_that_supports_care": ["Keeping a diary of when movements happen and what came before", "Offering safe sensory alternatives: chewable jewellery, cushions, movement breaks", "Reducing overload: noise, demands, transitions", "Support for carers, as this can be frightening and exhausting"],
  "guideline_refs": ["src-nice-ng11"]},
 "when_to_reach_out": "If a child's repetitive movements are causing injury, stopping them from playing or learning, or are new or sudden, ask a doctor for an assessment. Sudden onset of self-injury can signal pain or illness and needs checking.",
 "is_not": "Stimming in autistic people that doesn't cause harm is not a disorder and shouldn't be treated as one. Tics are faster, less rhythmic, and preceded by an urge. Compulsions in OCD are done on purpose to relieve anxiety. Trichotillomania and skin-picking have their own diagnoses.",
 "hope_note": "When the reason behind a movement is understood, families and teams can find safer ways to meet the need, and children can keep the comfort without the harm.",
 "in_young_people": "Stereotypies usually begin before age three. In typically developing children they often fade; in children with developmental disabilities they may persist and need ongoing support.",
 "related_topics": ["autism-spectrum-disorder", "intellectual-developmental-disorder", "tic-disorders", "trichotillomania", "excoriation-disorder"],
 "glossary_terms": ["stimming", "tic", "sensory-sensitivity", "occupational-therapist"],
 "safety": STD(["Mentions self-injury in a developmental context, without method detail. Site-wide crisis link stays one tap away."]),
 "visual": VIS("Soft line illustration of a child on a soft swing in a sensory room with gentle lights, an adult sitting nearby with a basket of cushions. Pastel green and lilac.", "A child sits on a soft swing in a sensory room with gentle lights while an adult sits nearby with a basket of cushions."),
 "communities": ["nas-online-community"],
 "sources": [DSM("Neurodevelopmental Disorders"), src("src-nice-ng11", "Challenging behaviour and learning disabilities: prevention and interventions (NG11)", "NICE", "https://www.nice.org.uk/guidance/ng11", 2015, note="Not opened; recommends functional assessment and behaviour support before medication.")],
 "review": REV(["Find primary prevalence source.", "Verify a family community for severe intellectual disability (for example Challenging Behaviour Foundation, UK)."])})
